las, 'Liberation Mono', monospace;\n  font-size: 12px;\n  line-height: 1.7;\n  white-space: pre-wrap;\n  overflow-wrap: anywhere;\n  user-select: text;\n}\n\n/* ---------- 悬浮球: D 原稿拱窗, 46×58, 命中区=整个底座 ---------- */\n.bf-orb {\n  position: absolute;\n  width: 46px;\n  height: 58px;\n  display: grid;\n  place-items: center;\n  padding: 0;\n  border: 0;\n  border-radius: 23px 23px 6px 6px;\n  background: var(--bf-orb-bg);\n  color: var(--bf-orb-ink);\n  box-shadow: var(--bf-orb-shadow);\n  cursor: grab;\n  touch-action: none;\n  transition: background-color 0.16s ease, transform 0.16s ease;\n}\n.bf-orb-glyph {\n  position: relative;\n  width: 30px;\n  height: 40px;\n  border-radius: 15px 15px 3px 3px;\n  background: radial-gradient(70% 60% at 50% 70%, #ffd89a, #e9a85a 55%, #8a5a2a);\n  box-shadow: 0 0 16px rgba(240, 180, 100, 0.55);\n}\n.bf-orb-glyph::before,\n.bf-orb-glyph::after {\n  content: '';\n  position: absolute;\n  background: var(--bf-orb-bg);\n}\n.bf-orb-glyph::before { left: 50%; top: 0; bottom: 0; width: 2px; transform: translateX(-50%); }\n.bf-orb-glyph::after { left: 0; right: 0; top: 58%; height: 2px; }\n.bf-orb:hover { transform: translateY(-1px); }\n.bf-orb:hover .bf-orb-glyph { box-shadow: 0 0 24px rgba(240, 180, 100, 0.75); }\n.bf-orb:active { transform: scale(0.96); }\n.bf-orb.dragging { cursor: grabbing; transform: scale(0.97); }\n.bf-orb:focus-visible { outline: none; box-shadow: inset 0 0 0 2px var(--bf-orb-ink), var(--bf-orb-shadow); }\n.bf-orb-spinner { display: none; }\n.bf-orb:has(.bf-orb-spinner) .bf-orb-glyph { animation: bfLamp 1.6s ease-in-out infinite; }\n@keyframes bfLamp {\n  0%, 100% { filter: brightness(1); }\n  40% { filter: brightness(0.45); }\n  55% { filter: brightness(1.1); }\n  70% { filter: brightness(0.7); }\n}\n\n/* 遮罩不在 iframe 里: 打开时 iframe 被放大成整屏, 整屏遮罩会被 iframe 自己的裁剪吃掉。\n   遮罩由悬浮球界面.vue 画在酒馆页面上(#bf-panel-dim), 配色取 theme.ts 的 scrim token。 */\n\n/* ---------- 面板: D 原稿, 纸面在左, 竖签从右侧伸出 ---------- */\n.bf-panel {\n  position: fixed;\n  left: 50%;\n  top: 50%;\n  transform: translate(-50%, -50%);\n  animation: bfPanelIn 0.18s ease-out;\n  width: min(1120px, 95vw);\n  height: min(760px, calc(100dvh - 56px));\n  z-index: 2;\n  display: grid;\n  grid-template-columns: minmax(0, 1fr) 46px;\n  grid-template-rows: auto minmax(0, 1fr) auto;\n  grid-template-areas: 'bar tabs' 'view tabs' 'status tabs';\n  overflow: visible;\n  background: transparent;\n  color: var(--bf-ink);\n}\n/* 日版只换纸面, 不改变 D 的结构; 竖签与文字保持足够对比 */\n.bf-root[data-theme='light'] .bf-nav-item:not(.active) { color: #5e5b64; }\n.bf-root[data-theme='light'] .bf-summary dd { color: var(--bf-ink); }\n.bf-root[data-theme='light'] .bf-now { border-color: rgba(155, 110, 53, 0.25); }\n\n.bf-panel::before {\n  content: '';\n  grid-area: 1 / 1 / 4 / 2;\n  position: relative;\n  z-index: 1;\n  background: var(--bf-shell);\n  border-radius: var(--bf-radius-xl);\n  box-shadow: var(--bf-shadow);\n}\n.bf-topbar,\n.bf-main,\n.bf-rail-foot { position: relative; z-index: 3; }\n\n/* ---------- 顶栏品牌: 一盏小拱窗 ---------- */\n.bf-brand {\n  display: flex;\n  align-items: center;\n  gap: 10px;\n  min-width: 0;\n  flex: none;\n}\n.bf-brand-mark {\n  width: 22px;\n  height: 28px;\n  flex: none;\n  border-radius: 11px 11px 3px 3px;\n  background: radial-gradient(70% 60% at 50% 70%, #ffd89a, #e9a85a 60%, #8a5a2a);\n}\n.bf-brand-text { min-width: 0; }\n.bf-title {\n  margin: 0;\n  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', STSong, serif;\n  font-size: 19px;\n  font-weight: 600;\n  line-height: 1.2;\n}\n.bf-subtitle {\n  margin: 0;\n  font-size: 12px;\n  line-height: 1.7;\n  color: var(--bf-muted);\n}\n\n/* ---------- D 原稿: 右侧竖排索引签 ---------- */\n.bf-nav {\n  grid-area: tabs;\n  position: relative;\n  z-index: 0;\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  gap: 5px;\n  padding: 30px 0 0;\n  overflow: visible;\n}\n.bf-nav-item {\n  position: relative;\n  z-index: 0;\n  flex: none;\n  width: 40px;\n  padding: 16px 8px;\n  border: 0;\n  border-radius: 0 8px 8px 0;\n  background: #20273a;\n  box-shadow: inset 7px 0 8px -7px rgba(0, 0, 0, 0.7), 0 0 0 1px #2a3247;\n  color: #9aa0b2;\n  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', STSong, serif;\n  font-size: 14px;\n  font-weight: 600;\n  letter-spacing: 4px;\n  text-align: left;\n  writing-mode: vertical-rl;\n  cursor: pointer;\n  transition: transform 0.15s, color 0.15s;\n}\n.bf-nav-item:nth-child(2) { background: #251f2c; }\n.bf-nav-item:nth-child(3) { background: #1d2a2d; }\n.bf-nav-item:nth-child(4) { background: #29251f; }\n.bf-nav-item:nth-child(5) { background: #222433; }\n.bf-nav-item:hover { transform: translateX(3px); color: var(--bf-ink); }\n.bf-nav-item.active {\n  z-index: 2;\n  width: 50px;\n  transform: translateX(-8px);\n  padding: 16px 8px 30px 16px;\n  background: var(--bf-shell);\n  color: var(--bf-accent-text);\n  box-shadow: 4px 4px 10px rgba(0, 0, 0, 0.35), 0 0 0 1px var(--bf-line);\n  clip-path: inset(-12px -12px -12px 8px);\n}\n.bf-nav-item.active::after {\n  content: '';\n  position: absolute;\n  left: calc(50% + 4px);\n  bottom: 12px;\n  width: 5px;\n  height: 5px;\n  transform: translateX(-50%);\n  border-radius: 50%;\n  background: var(--bf-accent);\n  box-shadow: 0 0 8px 2px rgba(233, 180, 106, 0.6);\n}\n.bf-nav-label { white-space: nowrap; }\n.bf-root[data-theme='light'] .bf-nav-item { background: #d8d5ce; color: #686770; box-shadow: 0 0 0 1px #c5c1b7; }\n.bf-root[data-theme='light'] .bf-nav-item:nth-child(2) { background: #ded7df; }\n.bf-root[data-theme='light'] .bf-nav-item:nth-child(3) { background: #d5deda; }\n.bf-root[data-theme='light'] .bf-nav-item:nth-child(4) { background: #e3dccf; }\n.bf-root[data-theme='light'] .bf-nav-item:nth-child(5) { background: #dadbe3; }\n.bf-root[data-theme='light'] .bf-nav-item.active { background: var(--bf-shell); color: var(--bf-accent-text); }\n\n/* ---------- 底部状态 ---------- */\n.bf-rail-foot {\n  grid-area: status;\n  display: flex;\n  align-items: center;\n  gap: 8px;\n  padding: 8px 20px;\n  border-top: 1px solid var(--bf-line);\n  font-size: 12px;\n  min-height: 37px;\n}\n.bf-sync { display: flex; align-items: center; gap: 8px; color: var(--bf-muted); }\n.bf-dot { width: 7px; height: 7px; flex: none; border-radius: 50%; background: var(--bf-danger); }\n.bf-sync.ok .bf-dot { background: var(--bf-success); }\n.bf-rail-meta { margin-left: auto; color: var(--bf-muted); font-variant-numeric: tabular-nums; }\n\n/* ---------- 顶栏: 只放面包屑与三个操作 ---------- */\n.bf-workspace {\n  flex: 1;\n  min-width: 0;\n  min-height: 0;\n  display: flex;\n  flex-direction: column;\n}\n.bf-topbar {\n  grid-area: bar;\n  display: flex;\n  align-items: center;\n  gap: 16px;\n  padding: 14px 20px;\n  border-bottom: 1px solid var(--bf-line);\n}\n.bf-crumb {\n  min-width: 0;\n  margin-left: auto;\n  display: flex;\n  gap: 14px;\n  color: var(--bf-muted);\n  font-size: 12.5px;\n  font-variant-numeric: tabular-nums;\n  overflow: hidden;\n  white-space: nowrap;\n}\n.bf-crumb span { overflow: hidden; text-overflow: ellipsis; }\n.bf-crumb strong {\n  font-weight: 500;\n  color: var(--bf-secondary);\n}\n.bf-crumb-sep {\n  margin: 0 4px;\n  color: var(--bf-line);\n}\n.bf-top-actions {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n  flex: none;\n}\n\n/* ---------- 主内容 ---------- */\n.bf-main {\n  grid-area: view;\n  min-height: 0;\n  display: flex;\n  overflow: hidden;\n}\n.bf-page {\n  flex: 1;\n  min-width: 0;\n  min-height: 0;\n  overflow-y: auto;\n  padding: 24px 28px 32px;\n  animation: bfPageIn 0.16s ease-out;\n  scrollbar-width: thin;\n  scrollbar-color: var(--bf-control-line) transparent;\n}\n.bf-page-head {\n  display: flex;\n  align-items: flex-end;\n  justify-content: space-between;\n  gap: 20px;\n  margin-bottom: 25px;\n}\n.bf-page-title {\n  margin: 0;\n  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', STSong, serif;\n  font-size: 26px;\n  font-weight: 600;\n  line-height: 1.25;\n}\n.bf-page-sub {\n  margin: 4px 0 0;\n  font-size: 14px;\n  color: var(--bf-muted);\n  line-height: 1.7;\n}\n.bf-page-note {\n  margin: 0 0 20px;\n  max-width: 68ch;\n}\n.bf-summary {\n  display: grid;\n  grid-template-columns: repeat(4, minmax(0, 1fr));\n  gap: 0;\n  margin: 0 0 26px;\n}\n.bf-summary > div { padding: 4px 18px 4px 0; }\n.bf-summary > div + div { border-left: 1px solid var(--bf-line); padding-left: 18px; }\n.bf-summary dt { color: var(--bf-muted); font-size: 12.5px; }\n.bf-summary dd {\n  margin: 0;\n  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', STSong, serif;\n  font-size: 30px;\n  line-height: 1.2;\n  color: var(--bf-ink);\n  font-variant-numeric: tabular-nums;\n}\n.bf-section-head {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n  gap: 14px;\n  margin-bottom: 8px;\n}\n.bf-section-head h3 {\n  margin: 0;\n  font-size: 15px;\n  font-weight: 700;\n}\n.bf-block-title {\n  margin: 0 0 12px;\n  font-size: 15px;\n  font-weight: 700;\n}\n.bf-note {\n  margin: 0;\n  font-size: 12px;\n  color: var(--bf-muted);\n  line-height: 1.75;\n}\n.bf-hint {\n  margin: 4px 0 10px;\n  font-size: 12.5px;\n  line-height: 1.7;\n  color: var(--bf-muted);\n}\n.bf-field-label {\n  display: block;\n  margin-bottom: 5px;\n  font-size: 12px;\n  color: var(--bf-muted);\n  letter-spacing: 0.02em;\n}\n.bf-dot-sep {\n  color: var(--bf-line);\n}\n\n/* ---------- 通用控件 ---------- */\n.bf-btn {\n  display: inline-flex;\n  align-items: center;\n  justify-content: center;\n  gap: 6px;\n  min-height: 34px;\n  padding: 6px 14px;\n  border: 1px solid var(--bf-line);\n  border-radius: var(--bf-radius-sm);\n  background: transparent;\n  color: var(--bf-ink);\n  font-size: 14px;\n  white-space: nowrap;\n  cursor: pointer;\n  transition:\n    background-color 0.16s ease,\n    border-color 0.16s ease,\n    color 0.16s ease,\n    transform 0.16s ease,\n    opacity 0.16s ease;\n}\n.bf-btn:hover:not(:disabled) {\n  background: var(--bf-paper-hover);\n}\n.bf-btn:active:not(:disabled) {\n  transform: translateY(1px);\n}\n.bf-btn:disabled {\n  opacity: 0.5;\n  cursor: not-allowed;\n}\n.bf-btn-sm {\n  min-height: 30px;\n  padding: 4px 11px;\n  font-size: 13px;\n}\n.bf-btn-primary {\n  border-color: var(--bf-accent);\n  background: var(--bf-accent);\n  color: var(--bf-accent-ink);\n}\n.bf-btn-primary:hover:not(:disabled) {\n  background: var(--bf-accent);\n  border-color: var(--bf-accent);\n  opacity: 0.9;\n}\n.bf-btn-danger {\n  border-color: var(--bf-danger);\n  color: var(--bf-danger);\n}\n.bf-btn-danger:hover:not(:disabled) {\n  background: var(--bf-danger-soft);\n}\n.bf-btn-quiet {\n  border-color: transparent;\n  color: var(--bf-secondary);\n}\n.bf-btn-quiet.is-on {\n  border-color: var(--bf-love);\n  background: var(--bf-love-soft);\n  color: var(--bf-love-ink);\n}\n.bf-btn-quiet:disabled {\n  opacity: 0.5;\n}\n.bf-text-btn {\n  padding: 4px 2px;\n  border: 0;\n  background: none;\n  color: var(--bf-accent-text);\n  font-size: 12px;\n  cursor: pointer;\n  transition: color 0.16s ease;\n}\n.bf-text-btn:hover {\n  text-decoration: underline;\n  text-underline-offset: 3px;\n}\n.bf-icon-btn {\n  width: 34px;\n  height: 34px;\n  display: inline-grid;\n  place-items: center;\n  padding: 0;\n  border: 0;\n  border-radius: var(--bf-radius-sm);\n  background: transparent;\n  color: var(--bf-secondary);\n  cursor: pointer;\n  transition:\n    color 0.16s ease,\n    background-color 0.16s ease;\n}\n.bf-icon-btn:hover {\n  color: var(--bf-ink);\n  background: var(--bf-paper-hover);\n}\n.bf-actions {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  gap: 8px;\n}\n.bf-actions-tight {\n  margin: 2px 0 4px;\n}\n.bf-input {\n  width: 100%;\n  min-width: 0;\n  height: 32px;\n  padding: 0 10px;\n  border: 1px solid var(--bf-control-line);\n  border-radius: var(--bf-radius-sm);\n  background: var(--bf-field-bg);\n  color: var(--bf-ink);\n  font-size: 14px;\n  outline: none;\n  transition:\n    border-color 0.16s ease,\n    background-color 0.16s ease;\n}\n.bf-input:focus {\n  border-color: var(--bf-accent);\n}\n.bf-input-sm {\n  height: 32px;\n  font-size: 14px;\n}.bf-input::placeholder,\n.bf-textarea::placeholder {\n  color: var(--bf-muted);\n}\n.bf-textarea {\n  width: 100%;\n  min-width: 0;\n  padding: 8px 11px;\n  border: 1px solid var(--bf-control-line);\n  border-radius: var(--bf-radius-sm);\n  background: var(--bf-field-bg);\n  color: var(--bf-ink);\n  font-size: 14px;\n  line-height: 1.7;\n  resize: vertical;\n  outline: none;\n  transition: border-color 0.16s ease;\n}\n.bf-textarea:focus {\n  border-color: var(--bf-accent);\n}\n.bf-textarea-sm {\n  font-size: 12px;\n  min-height: 56px;\n}\n.bf-spinner {\n  width: 13px;\n  height: 13px;\n  flex: none;\n  display: inline-block;\n  border: 2px solid currentColor;\n  border-right-color: transparent;\n  border-radius: 50%;\n  opacity: 0.9;\n  animation: bf-spin 0.8s linear infinite;\n}\n.bf-avatar {\n  width: 40px;\n  height: 40px;\n  flex: none;\n  display: grid;\n  place-items: center;\n  border-radius: 50% 50% 8px 8px;\n  background: var(--bf-avatar1);\n  color: var(--bf-avatar1-ink);\n  font-family: 'Noto Serif SC', 'Source Han Serif SC', 'Songti SC', STSong, serif;\n  font-size: 17px;\n  font-weight: 400;\n}\n.bf-avatar-lg { width: 56px; height: 56px; font-size: 24px; }\n.bf-avatar-sm { width: 30px; height: 30px; font-size: 14px; }\n.bf-avatar-tone-1 {\n  background: var(--bf-avatar1);\n  color: var(--bf-avatar1-ink);\n}\n.bf-avatar-tone-2 {\n  background: var(--bf-avatar2);\n  color: var(--bf-avatar2-ink);\n}\n.bf-avatar-tone-3 {\n  background: var(--bf-avatar3);\n  color: var(--bf-avatar3-ink);\n}\n.bf-avatar-tone-4 {\n  background: var(--bf-avatar4);\n  color: var(--bf-avatar4-ink);\n}\n.bf-avatar-tone-5 {\n  background: var(--bf-avatar5);\n  color: var(--bf-avatar5-ink);\n}\n.bf-avatar-tone-6 {\n  background: var(--bf-avatar6);\n  color: var(--bf-avatar6-ink);\n}\n.bf-avatar-tone-7 {\n  background: var(--bf-avatar7);\n  